#include <iostream>
#include <deque>
#include <cassert>
template <typename T>
class MyCustomAllocator {
public:
  T* allocate(size_t n) {
    void* ptr = malloc(n * sizeof(T));
    if (ptr == nullptr) throw std::bad_alloc();
    std::cout << "Allocating at: " << ptr << std::endl; //Debug output
    return static_cast<T*>(ptr);
  }
  void deallocate(T* ptr, size_t n) {
    std::cout << "Deallocating at: " << ptr << std::endl; //Debug output
    free(ptr);
  }
};
int main() {
  std::deque<int, MyCustomAllocator<int>> myDeque;
  myDeque.push_back(10);
  myDeque.push_back(20);
  std::deque<int, MyCustomAllocator<int>> anotherDeque;
  anotherDeque.push_back(10);
  anotherDeque.push_back(20);
  assert(myDeque == anotherDeque); //Custom allocator affects operator== implementation
  return 0;
}
